{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana maximum allowable rent increase","requirement":"A landlord may not raise rent by more than 3% of current rent or 80% of the Consumer Price Index change, whichever is less. The current maximum allowable increase is 2.87%.","key_value":"Lesser of 3% or 80% of CPI; 2.87% for September 1, 2026 through August 31, 2027","coverage_conditions":"Rental units in the City of Santa Ana governed by the Rent Stabilization and Just Cause Eviction Ordinance; the page addresses Santa Ana landlords and tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"City of Santa Ana rental units under the Rent Stabilization and Just Cause Eviction Ordinance"},"exemptions":null,"penalty":"If a landlord charges a tenant a pass-through fee greater than $50, the landlord shall reimburse the tenant for the registration fee pass-through overpayment.","effective_date":"2026-09-01","citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord can only raise your rent by a certain amount each year. The increase cannot be more than 3% of your current rent or 80% of the Consumer Price Index (CPI) change, whichever is less.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction requirement","requirement":"A landlord must have a valid reason to evict, such as nonpayment of rent, breaking the lease, or the landlord moving into the property. For certain reasons the landlord may have to help pay moving costs.","key_value":null,"coverage_conditions":"Rental units in the City of Santa Ana governed by the Rent Stabilization and Just Cause Eviction Ordinance; the page addresses Santa Ana landlords and tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"City of Santa Ana rental units under the Rent Stabilization and Just Cause Eviction Ordinance"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
